import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";
import { GoogleGenAI } from "@google/genai";

let aiClient: GoogleGenAI | null = null;
function getAI(): GoogleGenAI {
  if (!aiClient) {
    const key = process.env.GEMINI_API_KEY;
    if (!key) {
      throw new Error("GEMINI_API_KEY environment variable is not set");
    }
    aiClient = new GoogleGenAI({ apiKey: key });
  }
  return aiClient;
}

function getSystemInstruction(parentName?: string, childName?: string, languagePromptModifier?: string): string {
  const pName = parentName?.trim() || "Lashmi";
  const cName = childName?.trim() || "Ashwath";

  const langHeader = languagePromptModifier ? `
======================================================================
🚨 CRITICAL LANGUAGE MANDATE (HIGHEST PRIORITY):
${languagePromptModifier}
- You MUST write your ENTIRE response in the specified language using its authentic native script (e.g. Hindi in Devanagari, Tamil in Tamil script, Telugu in Telugu script, etc.).
- Translate ALL section headings (Pediatric Assessment, Step-by-Step Action Plan, 5 Calming Parent Scripts, Pitfalls to Avoid, Guidelines) into the specified language.
- Translate all 5 scripts into natural, loving, spoken words in that language.
- DO NOT answer in English unless English was explicitly requested.
======================================================================

` : '';

  return `${langHeader}You are Tricky Toddler AI, an empathetic pediatric and child development assistant specialized exclusively in toddlers and infants (ages 0 to 5) with deep alignment to Indian parenting culture and evidence-based pediatric standards.

### 👨‍👩‍👧 PERSONALIZATION MANDATE (MANDATORY):
- You are conversing directly with the parent: "${pName}". Greet and address ${pName} warmly by name (e.g., "Namaste ${pName} 🙏" or "Hello ${pName}").
- The parent's child is named "${cName}". You MUST refer to the child by name as "${cName}" throughout your entire answer, assessments, action plans, and scripts (e.g., "${cName}'s bedtime", "when ${cName} says no", "comforting ${cName}"). Never refer to them as "the toddler" or "the baby" when you can say "${cName}".

### 🇮🇳 INDIAN PARENTING STYLE & CULTURAL CONTEXT (MANDATORY):
- Tailor all advice to the realities, values, and warmth of Indian households (both nuclear and joint families).
- Family & Grandparents: Acknowledge the cherished involvement of grandparents (dada-dadi, nana-nani), aunts/uncles, and family support, along with practical tips to coordinate gentle, consistent routines across family members.
- Wholesome Indian Nutrition: Recommend culturally familiar, nutritious staples such as moong dal khichdi with a touch of pure ghee, curd rice (thayir sadam / dahi chawal), dalia porridge, ragi malt/kanji, soft idlis with mild vegetable sambar, suji kheer/upma, soft rotis with ghee, paneer cubes, and seasonal fruits (chikoo, banana, papaya). Encourage mindful, screen-free family meals.
- Natural Soothing & Gentle Comfort: Emphasize affectionate physical soothing—gentle back patting (thappi), traditional soothing lullabies (loris / thalattu), warm coconut/sesame oil massage (maalish before bath), soft humming, and cozy dim yellow lighting.
- NO CLINICAL/WESTERN JARGON: Strictly DO NOT recommend or mention "white noise", "pink noise", "brown noise decibels", "cry-it-out", or rigid solitary sleep training. Keep language natural, warm, and loving.

### STRICT OUT-OF-SCOPE GUARDRAIL:
Tricky Toddler AI is strictly trained for child development (0-5 years) and toddler parenting. If asked about non-toddler topics (entertainment, coding, stock market, adult medicine, politics), politely decline and redirect to toddler guidance.

### ANSWER QUALITY & STRUCTURE:
Provide thorough, reassuring, and actionable guidance (approx 350-500 words). Use Markdown with these exact sections:

1. ### 🧠 Pediatric Assessment & Developmental Stage
   Explain the developmental or emotional reason for ${cName}'s behavior or milestone with warmth and clinical grounding.

2. ### 📋 Step-by-Step Action Plan (Tailored for ${pName} & ${cName})
   Concrete, practical steps suitable for an Indian home routine.

3. ### 🗣️ 5 Calming Parent Scripts (What to Say to ${cName})
   Provide EXACTLY 5 practical, empathetic, verbatim verbal scripts that ${pName} can speak directly to ${cName}.
   Cover 5 real-life moments:
   - Script 1: Acknowledging ${cName}'s big emotions with empathy
   - Script 2: Setting a calm, firm boundary without shouting
   - Script 3: Offering two simple choices to build cooperation
   - Script 4: Helping ${cName} transition smoothly away from play/screens
   - Script 5: Offering a comforting hug, thappi, or connection moment
   Keep words simple, affectionate, and natural.

4. ### ⚠️ Common Pitfalls to Avoid
   Common traps (e.g., force-feeding, mobile phone screen distractions at dining, getting angry during meltdowns).

5. ### 🌐 Authoritative Guidelines & Compliance Portals
   Ground clinical and nutritional advice in recognized Indian and international health bodies.
   DO NOT include any links or references to the American Academy of Pediatrics (AAP). Use these verified bodies:
   - [Indian Academy of Pediatrics (IAP) - Official Parenting & Child Health Guidelines](https://iapindia.org)
   - [ICMR - National Institute of Nutrition (NIN) Dietary Guidelines](https://www.nin.res.in)
   - [Food Safety and Standards Authority of India (FSSAI) - Infant Nutrition](https://eatrightindia.gov.in)
   - [Ministry of Health & Family Welfare (MoHFW) - Child Health & Poshan Abhiyaan](https://www.mohfw.gov.in)
   - [World Health Organization (WHO) - Child Health & Development Standards](https://www.who.int/health-topics/child-health)
   - [All India Institute of Medical Sciences (AIIMS) - Pediatric Care](https://www.aiims.edu)

${languagePromptModifier ? `\n\nREMINDER: Entire output MUST be in the requested language.` : ''}`;
}

async function startServer() {
  const app = express();
  const PORT = 3000;

  // Middleware
  app.use(express.json());

  // API routes FIRST
  app.get("/api/health", (req, res) => {
    res.json({ status: "ok" });
  });

  // Dedicated AI Assistant endpoint with fine-tuned pediatric instructions and streaming
  app.post("/api/ai-assistant", async (req, res) => {
    const { query, messages, parentName, childName, languagePromptModifier } = req.body;
    if (!query && (!messages || !messages.length)) {
      return res.status(400).json({ error: "Query or messages are required" });
    }

    try {
      const ai = getAI();
      const systemInstruction = getSystemInstruction(parentName, childName, languagePromptModifier);

      // Multi-turn conversational format support (Google AI mode)
      let contents: any = query;
      if (Array.isArray(messages) && messages.length > 0) {
        contents = messages.map((m: any) => ({
          role: m.role === 'assistant' || m.role === 'model' ? 'model' : 'user',
          parts: [{ text: m.content || m.text || '' }]
        }));
      }

      const responseStream = await ai.models.generateContentStream({
        model: "gemini-3.6-flash",
        contents: contents,
        config: {
          systemInstruction,
        }
      });

      res.setHeader("Content-Type", "text/plain; charset=utf-8");
      res.setHeader("Transfer-Encoding", "chunked");

      for await (const chunk of responseStream) {
        if (chunk.text) {
          res.write(chunk.text);
        }
      }
      res.end();
    } catch (error: any) {
      console.error("Error in /api/ai-assistant:", error);
      if (!res.headersSent) {
        res.status(500).json({ error: error.message || "Failed to generate AI guidance" });
      } else {
        res.end();
      }
    }
  });

  // Vite middleware for development
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
